1	package scan
2	
3	import (
4		"os"
5		"os/exec"
6	
7		"github.com/anthnel/devdesk/internal/config"
8		"github.com/anthnel/devdesk/internal/engine"
9	)
10	
11	// ToolSpec says how one scanner is invoked: from a binary or from an image run
12	// by the configured container engine, and which one.
13	//
14	// It replaces the `source ToolSource, image string` pair that every command
15	// builder used to take. That pair had nowhere to carry the configured binary
16	// path, which is why `scan.trivy_path` was declared, defaulted, tilde-expanded
17	// on load — and read by nothing (D27). Carrying all three together means a
18	// builder cannot see the source without also seeing what to run.
19	type ToolSpec struct {
20		Source ToolSource
21		// Binary is what to exec when Source is ToolSourceBinary: the configured
22		// path when there is one, else the plain name resolved on PATH.
23		Binary string
24		// Image is the OCI image when Source is ToolSourceContainer.
25		Image string
26		// HostSocket is the engine socket to bind-mount so a containerised Trivy
27		// can inspect an image the host holds. Empty means there is none to mount,
28		// which is rootless podman without `podman system service`; the builder
29		// then makes no mount rather than inventing a path (§3.67).
30		//
31		// Only the Trivy image path reads it. A directory scan mounts the
32		// directory and nothing else.
33		HostSocket string
34	}
35	
36	// TrivySpec, GitleaksSpec and PlumberSpec are how a resolved DependencyStatus
37	// is handed to the command builders.
38	func (d DependencyStatus) TrivySpec() ToolSpec {
39		return ToolSpec{
40			Source:     d.TrivySource,
41			Binary:     d.TrivyBinary,
42			Image:      d.TrivyImage,
43			HostSocket: d.ImageScanSocket,
44		}
45	}
46	
47	func (d DependencyStatus) GitleaksSpec() ToolSpec {
48		return ToolSpec{Source: d.GitleaksSource, Binary: d.GitleaksBinary, Image: d.GitleaksImage}
49	}
50	
51	func (d DependencyStatus) PlumberSpec() ToolSpec {
52		return ToolSpec{Source: d.PlumberSource, Binary: d.PlumberBinary, Image: d.PlumberImage}
53	}
54	
55	// toolResolution is what detection worked out for one scanner.
56	type toolResolution struct {
57		Available bool
58		Source    ToolSource
59		Binary    string
60		Version   string
61	}
62	
63	// resolveTool decides where one scanner runs from.
64	//
65	// The three preferences differ in exactly one way that matters: `binary` does
66	// **not** fall back to a container. That silent fallback is what kept D27 invisible
67	// — a configured path that was never read still produced working scans, run by
68	// something other than what was asked for. Asking for a binary and not having
69	// one is now an unavailable tool, which the dashboard reports.
