package scan

import (
	"os"
	"os/exec"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/engine"
)

// ToolSpec says how one scanner is invoked: from a binary or from an image run
// by the configured container engine, and which one.
//
// It replaces the `source ToolSource, image string` pair that every command
// builder used to take. That pair had nowhere to carry the configured binary
// path, which is why `scan.trivy_path` was declared, defaulted, tilde-expanded
// on load — and read by nothing (D27). Carrying all three together means a
// builder cannot see the source without also seeing what to run.
type ToolSpec struct {
	Source ToolSource
	// Binary is what to exec when Source is ToolSourceBinary: the configured
	// path when there is one, else the plain name resolved on PATH.
	Binary string
	// Image is the OCI image when Source is ToolSourceContainer.
	Image string
	// HostSocket is the engine socket to bind-mount so a containerised Trivy
	// can inspect an image the host holds. Empty means there is none to mount,
	// which is rootless podman without `podman system service`; the builder
	// then makes no mount rather than inventing a path (§3.67).
	//
	// Only the Trivy image path reads it. A directory scan mounts the
	// directory and nothing else.
	HostSocket string
}

// TrivySpec, GitleaksSpec and PlumberSpec are how a resolved DependencyStatus
// is handed to the command builders.
func (d DependencyStatus) TrivySpec() ToolSpec {
	return ToolSpec{
		Source:     d.TrivySource,
		Binary:     d.TrivyBinary,
		Image:      d.TrivyImage,
		HostSocket: d.ImageScanSocket,
	}
}

func (d DependencyStatus) GitleaksSpec() ToolSpec {
	return ToolSpec{Source: d.GitleaksSource, Binary: d.GitleaksBinary, Image: d.GitleaksImage}
}

func (d DependencyStatus) PlumberSpec() ToolSpec {
	return ToolSpec{Source: d.PlumberSource, Binary: d.PlumberBinary, Image: d.PlumberImage}
}

// toolResolution is what detection worked out for one scanner.
type toolResolution struct {
	Available bool
	Source    ToolSource
	Binary    string
	Version   string
}

// resolveTool decides where one scanner runs from.
//
// The three preferences differ in exactly one way that matters: `binary` does
// **not** fall back to a container. That silent fallback is what kept D27 invisible
// — a configured path that was never read still produced working scans, run by
// something other than what was asked for. Asking for a binary and not having
// one is now an unavailable tool, which the dashboard reports.
func resolveTool(pref, configuredPath, name, image string, engineAvailable bool, versionArgs ...string) toolResolution {
	useBinary := func() (toolResolution, bool) {
		path, ok := locateBinary(configuredPath, name)
		if !ok {
			return toolResolution{Source: ToolSourceNone}, false
		}
		return toolResolution{
			Available: true,
			Source:    ToolSourceBinary,
			Binary:    path,
			Version:   toolVersion(path, versionArgs...),
		}, true
	}

	useImage := func() (toolResolution, bool) {
		if !engineAvailable || !imageIsLocal(image) {
			return toolResolution{Source: ToolSourceNone}, false
		}
		return toolResolution{
			Available: true,
			Source:    ToolSourceContainer,
			Version:   containerToolVersion(image, versionArgs...),
		}, true
	}

	switch pref {
	case config.ToolSourceBinary:
		res, _ := useBinary()
		return res
	case config.ToolSourceImage:
		res, _ := useImage()
		return res
	default: // config.ToolSourceAuto, and an empty value from a config that predates the setting
		if res, ok := useBinary(); ok {
			return res
		}
		res, _ := useImage()
		return res
	}
}

// locateBinary returns the executable to run. A configured path is taken as
// given — it is the one thing the user stated explicitly — and only checked for
// existence; anything else is resolved on PATH.
func locateBinary(configuredPath, name string) (string, bool) {
	if configuredPath != "" {
		if info, err := os.Stat(configuredPath); err == nil && !info.IsDir() {
			return configuredPath, true
		}
		// A path that was set and does not exist resolves to nothing rather than
		// quietly falling through to PATH: the user named a file.
		return "", false
	}
	path, err := exec.LookPath(name)
	if err != nil || path == "" {
		return "", false
	}
	return path, true
}

// toolVersion asks the binary what it is. A tool that will not answer is still
// usable, so the version is best-effort.
func toolVersion(path string, args ...string) string {
	out, err := exec.Command(path, args...).Output()
	if err != nil {
		return ""
	}
	return string(out)
}

// containerToolVersion asks the image what it is, through the configured
// engine. The engine's name is part of the answer — it is what the dashboard
// shows to say where the tool is coming from.
func containerToolVersion(image string, args ...string) string {
	name := engine.Current().Name
	runArgs := append([]string{"run", "--rm", image}, args...)
	out, err := exec.Command(engine.Current().Binary, runArgs...).Output() //nolint:gosec // the binary is a declared engine name or a configured path
	if err != nil {
		return name
	}
	return name + ":" + string(out)
}

package scan

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"strings"
)

// toolCmd is one subprocess invocation: the binary and the arguments handed to
// it. Building it is pure, which is what makes the argument surface — the part
// that decides what a scanner is actually asked to do — testable without a
// scanner installed.
//
// It is also what the UI displays. Deriving the shown command and the executed
// one from the same value is the point: the two used to be built separately and
// had drifted (§1.3 D19).
type toolCmd struct {
	Name string
	Args []string
	// Env is the child's whole environment when it is not nil, os.Environ()
	// plus what the caller added. It exists so a credential can reach a tool
	// without going through argv, which is readable from the process list —
	// the arrangement the clone already uses for http.extraHeader (§3.16).
	//
	// String() never renders it: the invocation is logged and shown in the UI.
	Env []string

	// Dir is the working directory the tool runs in, when it has one.
	//
	// It exists for plumber, whose `analyze` takes **no path argument**: it
	// works on the current directory. Without this the tool ran in whatever
	// directory DevDesk was launched from and reported
	// `--project is required (could not auto-detect from git remote)` — a
	// failure about a repository nobody had asked it to look at. Trivy and
	// Gitleaks take their target in argv and set nothing here.
	Dir string
}

// String renders the invocation as a shell command line, for logs and for the
// command the UI shows next to a scan.
func (c toolCmd) String() string {
	if c.Name == "" {
		return ""
	}
	line := strings.Join(append([]string{c.Name}, c.Args...), " ")
	// The directory is part of what the command means when the tool takes no
	// path: a logged invocation that cannot be re-run says less than it looks
	// like it does.
	if c.Dir != "" {
		return "cd " + c.Dir + " && " + line
	}
	return line
}

// exitError reports a tool that ran and exited non-zero. The code matters:
// both scanners use a non-zero exit to mean "I found something" rather than
// "I failed" — trivy for vulnerabilities, gitleaks for secrets — so callers
// have to tell the two apart.
type exitError struct {
	Code   int
	Stderr string
}

func (e *exitError) Error() string {
	if e.Stderr != "" {
		return fmt.Sprintf("exit status %d: %s", e.Code, strings.TrimSpace(e.Stderr))
	}
	return fmt.Sprintf("exit status %d", e.Code)
}

// commandRunner is the seam every subprocess in this package passes through.
//
// The package drives trivy and gitleaks as external processes, which makes it
// untestable without both installed and a repository to point them at. Routing
// through this interface lets tests exercise the argument building, the
// exit-code handling and the output parsing — where the defects live — against
// canned output.
type commandRunner interface {
	// Run executes tc and returns what it wrote to stdout. Lines written to
	// stderr are forwarded to progressFn as they arrive, which is how Trivy
	// reports its database download. A tool that runs and exits non-zero
	// returns its stdout along with an *exitError.
	Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error)
}

// cliRunner is the production commandRunner: it shells out to the real tools.
type cliRunner struct{}

func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
	cmd := exec.CommandContext(ctx, tc.Name, tc.Args...) //nolint:gosec // name is one of trivy/gitleaks/plumber/docker
	cmd.Env = tc.Env                                     // nil inherits this process's environment, which is the default
	cmd.Dir = tc.Dir                                     // empty runs in DevDesk's own working directory

	var stdout bytes.Buffer
	cmd.Stdout = &stdout

	// Stderr is consumed two ways: streamed to progressFn while the tool runs,
	// and kept so a failure can be reported with the tool's own diagnostic.
	var stderr bytes.Buffer
	if progressFn != nil {
		pipe, err := cmd.StderrPipe()
		if err == nil {
			done := make(chan struct{})
			go func() {
				defer close(done)
				sc := bufio.NewScanner(pipe)
				for sc.Scan() {
					line := strings.TrimSpace(sc.Text())
					if line == "" {
						continue
					}
					stderr.WriteString(line)
					stderr.WriteByte('\n')
					progressFn(line)
				}
				// A read failure on the progress pipe is not a scan failure:
				// the report comes back on stdout, and the tool's exit code
				// says whether it succeeded. Dropping the rest of the progress
				// is the whole consequence.
				_ = sc.Err()
			}()
			if err := cmd.Start(); err != nil {
				return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
			}
			<-done // drain stderr before Wait closes the pipe
			return finish(tc.Name, cmd, &stdout, &stderr)
		}
	}

	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
	}
	return finish(tc.Name, cmd, &stdout, &stderr)
}

// finish waits for the tool and only then reads what it wrote.
//
// The order is the point, and it is not a style preference: os/exec fills the
// output buffers from goroutines it owns, and only Wait guarantees they are
// done. Reading the buffer in the same expression as Wait — which is what
// `return stdout.Bytes(), waitErr(..., cmd.Wait(), ...)` does, since operands
// are evaluated before the call — snapshots it while it is still empty, and
// every scan comes back with no findings.
func finish(name string, cmd *exec.Cmd, stdout, stderr *bytes.Buffer) ([]byte, error) {
	err := cmd.Wait()
	return stdout.Bytes(), waitErr(name, err, stderr.String())
}

// waitErr turns a non-zero exit into an *exitError carrying the code, and
// leaves anything else (a killed process, a broken pipe) as it is.
func waitErr(name string, err error, stderr string) error {
	if err == nil {
		return nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if stderr == "" {
			stderr = string(exitErr.Stderr)
		}
		return &exitError{Code: exitErr.ExitCode(), Stderr: stderr}
	}
	return fmt.Errorf("%s failed: %w", name, err)
}

// runner is swapped by tests. Production code never reassigns it, so the
// package stays safe to call concurrently; tests that swap it must not run in
// parallel.
var runner commandRunner = cliRunner{}

package scan

// Where a finding goes: one single definition, for everyone.
//
// There used to be two, which did not say the same thing. `CountFindings`
// classified on `Source` alone and sent everything else to the severity
// counters; the security view classified on `Source` plus `PkgName` plus
// `Match`. Three entries told them apart — a trivy finding with no
// `PkgName`, an unknown source, a trivy finding carrying a `Match` — and
// each produced a finding counted in the header's CVE bar but absent from
// every tab, so invisible in the table. Same family as D24, D25 and D26:
// two copies of one rule, one place to update.
//
// Classification is now done on the source and nothing else, which required
// giving Trivy secrets their own source (`trivy-secret`) instead of being
// recognized by the presence of a `Match`.

// The sources a scanner can produce. A source missing from this list is a
// programming defect, not user input: `Categorize` classifies it as a
// vulnerability, which keeps it visible in the CVE tab rather than making it
// disappear.
const (
	SourceTrivy          = "trivy"           // vulnerabilities
	SourceTrivySecret    = "trivy-secret"    // secrets detected by Trivy
	SourceTrivyLicense   = "trivy-license"   // licenses
	SourceTrivyMisconfig = "trivy-misconfig" // IaC misconfigurations
	SourceGitleaks       = "gitleaks"        // secrets detected by Gitleaks
	SourcePlumber        = "plumber"         // pipeline security score (§3.42)
)

// Category is the family a finding belongs to: a tab in the results view,
// and a counter on `Result`.
type Category int

const (
	CategoryVulnerability Category = iota
	CategorySecret
	CategoryLicense
	CategoryMisconfiguration
	CategoryCIScore
)

// Categorize returns the family a finding belongs to.
//
// It is the only function that decides, and `Result.CountFindings` as well
// as the security view's tabs go through it.
func Categorize(f Finding) Category {
	switch f.Source {
	case SourceGitleaks, SourceTrivySecret:
		return CategorySecret
	case SourceTrivyLicense:
		return CategoryLicense
	case SourceTrivyMisconfig:
		return CategoryMisconfiguration
	case SourcePlumber:
		return CategoryCIScore
	default:
		return CategoryVulnerability
	}
}

package scan

import "github.com/anthnel/devdesk/internal/config"

// OptionsFromConfig builds the scan options a context is configured with.
//
// This is the only way ScanOptions is assembled. Three call sites used to do it
// by hand — the security form, the workspaces list and the images list — and
// they had drifted: only the form set IgnoreEOL, so the option applied when
// scanning from the form and silently did not from either list (D26).
//
// OnProgress is deliberately left nil: it is per-scan wiring, not configuration,
// and belongs to whoever starts the scan. So is LoadForgeToken, which needs the
// context's secret store — the caller has it, this function does not.
//
// It takes the whole Config rather than its Scan section because the CI stage
// needs the forge: which platform a context targets is what decides whether a
// repository is graded at all (§3.42), and that is not a scan setting.
func OptionsFromConfig(cfg *config.Config) ScanOptions {
	c := cfg.Scan
	// The address is kept in the config even when the checkbox is off, so
	// switching it back on does not lose what was typed — but a scan must not
	// see it until the checkbox says client-server mode is wanted.
	trivyServer := ""
	if c.UseTrivyServer {
		trivyServer = c.TrivyServer
	}
	return ScanOptions{
		EnableCIScore:   c.EnableCIScore,
		PlumberSource:   c.PlumberSource,
		PlumberPath:     c.PlumberPath,
		PlumberImage:    c.PlumberImage,
		PlumberConfig:   c.PlumberConfig,
		Forge:           cfg.Forge,
		EnableVuln:      c.EnableVuln,
		EnableSecret:    c.EnableSecret,
		EnableLicense:   c.EnableLicense,
		EnableMisconfig: c.EnableMisconfig,
		TrivySource:     c.TrivySource,
		TrivyPath:       c.TrivyPath,
		TrivyImage:      c.TrivyImage,
		GitleaksSource:  c.GitleaksSource,
		GitleaksPath:    c.GitleaksPath,
		GitleaksImage:   c.GitleaksImage,
		TrivyServer:     trivyServer,
		IgnoreUnfixed:   c.IgnoreUnfixed,
		IgnoreEOL:       c.IgnoreEOL,
		GitleaksHistory: c.GitleaksHistory,
		GitleaksConfig:  c.GitleaksConfig,
	}
}

package scan

import (
	"context"
	"errors"
	"fmt"
	"os"

	"github.com/anthnel/devdesk/internal/engine"
)

// plumber reads a repository's CI configuration — GitHub workflows, .gitlab-ci
// — through a Rego policy engine and grades it: a letter from A to E, points
// out of 100, and the issues that explain them (§3.42).
//
// Everything here is measured on plumber 0.4.40 and 0.4.42, by real runs. The
// section it implements was twice wrong about this tool from reading its
// documentation, so nothing below is inferred.

// Exit codes. Four, not three: `3` says the analysis ran on incomplete data and
// the score is withheld, and it is the one that matters most here — it maps
// exactly onto the `?` state of the CI column, without anyone having to read
// dataCollectionDegraded out of the JSON to find out.
const (
	plumberGateFailed    = 1 // a score exists and is below --min-points
	plumberRuntimeError  = 2 // no token, bad config, unreachable host, no repository
	plumberScoreWithheld = 3 // it ran, and says it cannot conclude
)

// plumberConfigMount is where a configured rules file is mounted inside the
// container, on §3.50's model: the argument plumber sees is never the host path.
//
// The container root is free of everything except /plumber, the binary itself
// (checked on getplumber/plumber). The repository is mounted at
// containerScanPath, so no file of it can land beside this one.
const plumberConfigMount = "/plumber.yaml"

// plumberSafeDirectory is what lets a containerised plumber read the mounted
// repository at all.
//
// The image runs as uid 65532, so git refuses the mount with `fatal: detected
// dubious ownership in repository at '/scan'` and plumber answers *could not
// determine the provider: not in a git repository*. Passing it through the
// environment rather than a config file is what keeps the mount read-only and
// the user non-root; `--user` is not portable to Windows hosts. Measured, not
// deduced: `--provider` alone does **not** lift it.
var plumberSafeDirectory = []string{
	"-e", "GIT_CONFIG_COUNT=1",
	"-e", "GIT_CONFIG_KEY_0=safe.directory",
	"-e", "GIT_CONFIG_VALUE_0=" + containerScanPath,
}

// PlumberOptions is what one plumber run needs beyond the tool itself.
type PlumberOptions struct {
	// Provider is the forge this context targets, declared rather than sniffed
	// from the remote: config.ForgeGitLab or config.ForgeGitHub.
	Provider string
	// Branch is the repository's current branch. It is passed and the failure
	// accepted: a score describing the default branch when the user is looking
	// at another one would be right about something they did not ask about.
	// The flag has no effect on the GitHub local path, which reads the tree.
	Branch string
	// ConfigPath is scan.plumber_config, already absolute (config.ExpandPaths).
	ConfigPath string
	// Token is the context's forge token. It reaches plumber through the
	// environment, never argv, which is readable from the process list.
	Token string
	// GitLabURL is the instance to talk to on the GitLab path.
	GitLabURL string
}

// plumberArgs builds the invocation.
//
// The JSON leaves by two different routes, and the asymmetry is measured rather
// than chosen: in a container `--output /dev/stdout` works, and for a native
// Windows binary it writes nothing at all — there is no such path. So the
// binary mode writes to a file the caller passes in and deletes.
//
// `--print=false` is what keeps stdout pure JSON: the human report and the
// score banner both go there otherwise. The tool's own logs go to stderr, which
// is where progressFn reads them.
func plumberArgs(target string, tool ToolSpec, opts PlumberOptions, outPath string) toolCmd {
	docker := tool.Source == ToolSourceContainer

	configFlag := opts.ConfigPath
	if docker && opts.ConfigPath != "" {
		configFlag = plumberConfigMount
	}

	options := []string{"analyze", "--score", "--print=false", "--output", outPath}
	if opts.Provider != "" {
		options = append(options, "--provider", opts.Provider)
	}
	if opts.Branch != "" {
		options = append(options, "--branch", opts.Branch)
	}
	if opts.GitLabURL != "" {
		options = append(options, "--gitlab-url", opts.GitLabURL)
	}
	if opts.ConfigPath != "" {
		options = append(options, "--config", configFlag)
	}

	if docker {
		args := []string{"run", "--rm", "-v", target + ":" + containerScanPath + ":ro"}
		if opts.ConfigPath != "" {
			// Before the image name: everything after it is plumber's own argv.
			args = append(args, "-v", opts.ConfigPath+":"+plumberConfigMount+":ro")
		}
		args = append(args, plumberSafeDirectory...)
		args = append(args, plumberTokenEnv(opts)...)
		args = append(args, "-w", containerScanPath, plumberImage(tool.Image))
		return toolCmd{Name: engine.Current().Binary, Args: append(args, options...)}
	}

	// Dir, not an argument: `analyze` works on the current directory and takes
	// no path. The container gets the same thing through -w.
	return toolCmd{Name: plumberBinary(tool), Args: options, Dir: target}
}

// plumberTokenEnv passes the context's token to a containerised plumber.
//
// The variable differs by forge, and naming both would send a GitLab token to
// GitHub on a repository that answers to neither. An empty token declares
// nothing rather than an empty variable: plumber treats "set but empty" as an
// attempt, and its diagnostic is then about a rejected credential rather than
// about a missing one.
func plumberTokenEnv(opts PlumberOptions) []string {
	if opts.Token == "" {
		return nil
	}
	name := "GH_TOKEN"
	if opts.Provider == providerGitLab {
		name = "GITLAB_TOKEN"
	}
	return []string{"-e", name + "=" + opts.Token}
}

func plumberImage(image string) string {
	if image == "" {
		return DefaultPlumberImage
	}
	return image
}

func plumberBinary(tool ToolSpec) string {
	if tool.Binary != "" {
		return tool.Binary
	}
	return "plumber"
}

// providerGitLab and providerGitHub are the values --provider takes. They are
// stated here as well as in internal/config because scan must not import a
// forge backend and config must not be the authority on a tool's flags;
// TestThePlumberProviderVocabularyMatchesTheConfig holds the two in step, the
// same arrangement as the registry provider names.
const (
	providerGitLab = "gitlab"
	providerGitHub = "github"
)

// PlumberReport is what one run says about a repository, beyond its findings.
type PlumberReport struct {
	// Score is the letter, empty when it was withheld.
	Score string
	// Points is finalPoints out of 100, and it is a float: a score is a
	// weighted sum, so a whole number is the exception rather than the shape.
	Points float64
	// Withheld reports a run that could not conclude — exit 3, and
	// dataCollectionDegraded in the JSON. Its letter must never be shown: a
	// degraded run of the fixture reads B/79 where the complete run reads E/30,
	// because a control that did not run found nothing.
	Withheld bool
	// Reasons is why, when it was withheld.
	Reasons []string
	// CIMissing reports a repository with no pipeline at all, which is not a
	// bad score.
	CIMissing bool
	// Findings are the issues, with their severity joined on from the score
	// block.
	Findings []Finding
}

// RunPlumber executes plumber and returns what it found.
func RunPlumber(ctx context.Context, target string, tool ToolSpec, opts PlumberOptions, progressFn func(string)) (*PlumberReport, error) {
	if err := checkPlumberConfig(opts.ConfigPath); err != nil {
		return nil, err
	}

	outPath, read, cleanup, err := plumberOutput(tool)
	if err != nil {
		return nil, err
	}
	defer cleanup()

	cmd := plumberArgs(target, tool, opts, outPath)
	if tool.Source != ToolSourceContainer && opts.Token != "" {
		cmd.Env = plumberBinaryEnv(opts)
	}

	stdout, runErr := runner.Run(ctx, cmd, progressFn)

	// Only exit 2 is a failure. 0 and 1 are verdicts — the gate is set at 100
	// points by default, so 1 is the common case — and 3 is plumber saying it
	// could not conclude, which is an answer this package carries rather than
	// an error it raises.
	if runErr != nil {
		var exit *exitError
		if !errors.As(runErr, &exit) || exit.Code == plumberRuntimeError {
			return nil, fmt.Errorf("plumber failed: %w", runErr)
		}
		if exit.Code != plumberGateFailed && exit.Code != plumberScoreWithheld {
			return nil, fmt.Errorf("plumber failed: %w", runErr)
		}
	}

	data, err := read(stdout)
	if err != nil {
		return nil, fmt.Errorf("plumber wrote no report: %w", err)
	}
	return parsePlumberOutput(data)
}

// plumberOutput decides where the JSON goes, and how to get it back.
//
// See plumberArgs: a container writes it to stdout, a native binary to a file,
// because a Windows plumber writes nothing at all to /dev/stdout (measured).
func plumberOutput(tool ToolSpec) (path string, read func([]byte) ([]byte, error), cleanup func(), err error) {
	if tool.Source == ToolSourceContainer {
		return "/dev/stdout", func(stdout []byte) ([]byte, error) {
			if len(stdout) == 0 {
				return nil, errors.New("empty stdout")
			}
			return stdout, nil
		}, func() {}, nil
	}

	f, err := os.CreateTemp("", "devdesk-plumber-*.json")
	if err != nil {
		return "", nil, func() {}, fmt.Errorf("plumber report file: %w", err)
	}
	name := f.Name()
	_ = f.Close()
	return name, func([]byte) ([]byte, error) { return os.ReadFile(name) }, func() { _ = os.Remove(name) }, nil
}

// plumberBinaryEnv hands the token to a plumber running on this machine. Same
// rule as the container's: one variable, chosen by provider.
func plumberBinaryEnv(opts PlumberOptions) []string {
	name := "GH_TOKEN"
	if opts.Provider == providerGitLab {
		name = "GITLAB_TOKEN"
	}
	return append(os.Environ(), name+"="+opts.Token)
}

// checkPlumberConfig refuses a rules file that cannot be read, before anything
// starts — §3.50's guard, for §3.50's reason. It is not there to catch a bad
// configuration: plumber says that itself, loudly, and exits 2. It is there
// because `docker run -v` on a host path that does not exist does not fail, it
// creates a directory at that path and mounts it.
func checkPlumberConfig(path string) error {
	if path == "" {
		return nil
	}
	f, err := os.Open(path) //nolint:gosec // the path is the user's own setting
	if err != nil {
		return fmt.Errorf("plumber config: %w", err)
	}
	return f.Close()
}

// GetPlumberCommand returns the command that would be executed, for display and
// logging. Built by the same builder as the executed one, so the two cannot
// drift apart — and with the token left out, because this string is logged.
func GetPlumberCommand(target string, tool ToolSpec, opts PlumberOptions) string {
	opts.Token = ""
	return plumberArgs(target, tool, opts, "<report>").String()
}

