package scan

import (
	"fmt"
	"net/url"
	"strings"

	"github.com/anthnel/devdesk/internal/engine"
)

// Building a Trivy invocation is pure: the same inputs produce the command that
// is run and the command that is shown. Keeping the two derived from one
// builder is what stops them drifting apart (§1.3 D19).

// containerScanPath is where a scanned directory is mounted inside the tool's
// container, so the argument passed to the tool is never the host path.
const containerScanPath = "/scan"

// socketMount is how a containerised Trivy reaches images the host engine
// holds: the engine's own socket, bind-mounted read-only at the path Trivy
// looks for it. It is a broad grant, so it is only made when there is no Trivy
// server to do the work instead.
//
// The container side stays /var/run/docker.sock whatever the engine, because
// that is where Trivy looks; only the host side moves. An empty socket produces
// no mount at all — under rootless podman there is nothing to mount unless
// `podman system service` is running, and inventing a path that is not there
// would turn a refusal the UI can explain into a container that fails on
// startup (§3.67).
const trivySocketPath = "/var/run/docker.sock"

func socketMount(hostSocket string) (string, bool) {
	if hostSocket == "" {
		return "", false
	}
	return hostSocket + ":" + trivySocketPath + ":ro", true
}

// serverAddr normalises the configured Trivy server address, refusing one Trivy
// cannot use.
//
// Trivy parses this as a URL and fails the entire scan when it cannot. A single
// stray ":" in the field — which is easy to get, since a bare ":" typed while
// the field has focus is a character rather than the command line (§3.7) —
// produces
//
//	FATAL flag error: unable to convert flags to options:
//	invalid server address format: parse ":": missing protocol scheme
//
// a message naming neither DevDesk nor the setting it came from. Worse, the
// field is persisted on every option toggle, so one keystroke breaks every
// later scan from every view until it is found in the config file.
//
// Surrounding space is not an address, so it trims to nothing and client-server
// mode is simply off. Anything else that is not an absolute URL is refused
// here, where the message can say where to fix it.
// ValidateTrivyServer reports whether a Trivy server address can be used, so a
// form can refuse it while the user is still looking at the field rather than
// letting the failure surface as a scan warning minutes later.
func ValidateTrivyServer(server string) error {
	_, err := serverAddr(server)
	return err
}

func serverAddr(server string) (string, error) {
	trimmed := strings.TrimSpace(server)
	if trimmed == "" {
		return "", nil
	}
	// Hostname() rather than Host: "http://:" parses with a Host of ":" and no
	// hostname at all, which is not somewhere a request can be sent.
	parsed, err := url.Parse(trimmed)
	if err != nil || parsed.Scheme == "" || parsed.Hostname() == "" {
		return "", fmt.Errorf(
			"trivy server address %q is not a URL (want http://host:port) — fix or clear scan.trivy_server", trimmed)
	}
	return trimmed, nil
}

// trivyArgs builds a vulnerability or license scan.
func trivyArgs(target string, targetType TargetType, licenseMode bool, tool ToolSpec,
	server string, ignoreUnfixed, ignoreEOL bool) (toolCmd, error) {
	return buildTrivyArgs(target, targetType, licenseMode, tool, server, ignoreUnfixed, ignoreEOL, false)
}

// trivyRemoteImageArgs builds the vulnerability scan of an image read straight
// from its registry (`--image-src remote`) instead of from the local engine.
//
// That is what lets a candidate base image be scanned without pulling it: no
// image lands in the engine's storage, and the container-mode invocation needs
// no engine socket. Measured on Trivy 0.74.0, in container mode with no socket
// mounted (§3.2).
func trivyRemoteImageArgs(image string, tool ToolSpec, server string, ignoreUnfixed, ignoreEOL bool) (toolCmd, error) {
	return buildTrivyArgs(image, TargetImage, false, tool, server, ignoreUnfixed, ignoreEOL, true)
}

func buildTrivyArgs(target string, targetType TargetType, licenseMode bool, tool ToolSpec,
	server string, ignoreUnfixed, ignoreEOL, remoteImage bool) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json"}
		if licenseMode {
			args = append(args, "--scanners", "license")
		} else {
			args = append(args, "--scanners", "vuln")
		}
	case TargetImage:
		// --scanners vuln explicitly: Trivy's default for an image is
		// "vuln,secret", so this stage was running the secret scanner on every
		// image scan and throwing its output away. Secrets are the secret
		// stage's job, and asking for them twice would report each one twice.
		args = []string{"image", "--format", "json", "--scanners", "vuln"}
		if remoteImage {
			args = append(args, "--image-src", "remote")
		}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}
	if ignoreUnfixed {
		args = append(args, "--ignore-unfixed")
	}
	if ignoreEOL {
		args = append(args, "--ignore-status", "end_of_life")
	}

	return wrapTrivy(args, target, targetType, tool, server, remoteImage), nil
}

// trivySecretArgs builds a secret scan. Like misconfiguration, it reads content
// rather than a package manifest, so it applies to both target types — which is
// what gives an image scan a secret stage at all, Gitleaks being directory-only.
func trivySecretArgs(target string, targetType TargetType, tool ToolSpec, server string) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json", "--scanners", "secret"}
	case TargetImage:
		args = []string{"image", "--format", "json", "--scanners", "secret"}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}

	// No --ignore-status: end_of_life describes a package's support window and
	// says nothing about a secret sitting in a file.
	return wrapTrivy(args, target, targetType, tool, server, false), nil
}

// trivyMisconfigArgs builds a misconfiguration scan. It reads configuration
// files rather than a package manifest, so it applies to both target types.
func trivyMisconfigArgs(target string, targetType TargetType, tool ToolSpec,
	server string, ignoreEOL bool) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json", "--scanners", "misconfig"}
	case TargetImage:
		args = []string{"image", "--format", "json", "--scanners", "misconfig"}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}
	if ignoreEOL {
		args = append(args, "--ignore-status", "end_of_life")
	}

	return wrapTrivy(args, target, targetType, tool, server, false), nil
}

// wrapTrivy turns tool arguments into the invocation to run: either trivy
// directly, or docker run with the target mounted and the tool arguments
// appended after the image.
//
// noSocket says the scan reads its image from the registry, so the engine
// socket is not mounted: nothing would use it.
func wrapTrivy(args []string, target string, targetType TargetType, tool ToolSpec, server string, noSocket bool) toolCmd {
	if tool.Source != ToolSourceContainer {
		return toolCmd{Name: trivyBinary(tool), Args: append(args, target)}
	}

	engineArgs := []string{"run", "--rm"}
	if targetType == TargetDirectory {
		engineArgs = append(engineArgs, "-v", target+":"+containerScanPath+":ro")
		args = append(args, containerScanPath)
	} else {
		if server == "" && !noSocket {
			if mount, ok := socketMount(tool.HostSocket); ok {
				engineArgs = append(engineArgs, "-v", mount)
			}
		}
		args = append(args, target)
	}
	engineArgs = append(engineArgs, trivyImage(tool.Image))
	return toolCmd{Name: engine.Current().Binary, Args: append(engineArgs, args...)}
}

// trivyBinary is what to exec for a binary-source scan: the resolved path when
// detection found one, else the plain name. The fallback keeps the pure arg
// builders usable from tests that never ran detection.
func trivyBinary(tool ToolSpec) string {
	if tool.Binary != "" {
		return tool.Binary
	}
	return "trivy"
}

func gitleaksBinary(tool ToolSpec) string {
	if tool.Binary != "" {
		return tool.Binary
	}
	return "gitleaks"
}

func trivyImage(image string) string {
	if image == "" {
		return DefaultTrivyImage
	}
	return image
}

func gitleaksImage(image string) string {
	if image == "" {
		return DefaultGitleaksImage
	}
	return image
}

package scan

import (
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/git"
)

// Which repositories plumber grades, decided in one place.
//
// A context targets one forge and one only (§3.6), so it has one session and
// one token: a GitHub context grades its GitHub repositories, a GitLab context
// its GitLab ones, and a repository of any other host is **not scannable**
// rather than scanned without credentials. That is §3.17's rule — a personal
// access token authenticates one host, and workspaces_dir holds whatever the
// user has cloned — asked here for a second reason.
//
// It lives in this package rather than in the two views that start scans,
// because two copies of a rule is what D26 was: only the form set IgnoreEOL, so
// the option applied from one screen and silently did not from the others.

// ciOptions decides whether plumber runs on this target, and with what.
//
// It is resolved **per target, not per batch**: one batch holds repositories
// with different remotes and different branches, so a single set of options for
// all of them would grade the wrong thing — or grade a repository of another
// forge, which is the whole point of the rule.
//
// The remote is read here rather than passed in because this is the only place
// that needs it and the two views that start scans would otherwise each carry
// the rule. Reading it costs one `git` call per repository, and only when the
// setting is on.
func (s *Scanner) ciOptions(target string, targetType TargetType) (PlumberOptions, bool) {
	// An image has no pipeline, so there is nothing to grade.
	if !s.options.EnableCIScore || targetType != TargetDirectory || !s.deps.PlumberAvailable {
		return PlumberOptions{}, false
	}
	status, err := git.ReadStatus(target)
	if err != nil {
		// Not a repository: not a failure of the scan, just nothing to grade.
		return PlumberOptions{}, false
	}
	return ciOptionsFor(s.options, status.Remote, status.Branch, s.options.LoadForgeToken)
}

// ciOptionsFor is the rule itself, separated from the git read so a test can
// state it without a repository on disk.
func ciOptionsFor(o ScanOptions, remoteURL, branch string, loadToken func() string) (PlumberOptions, bool) {
	if !git.SameHost(remoteURL, o.Forge.URL) {
		return PlumberOptions{}, false
	}

	opts := PlumberOptions{
		Provider:   plumberProvider(o.Forge.Type),
		Branch:     branch,
		ConfigPath: o.PlumberConfig,
	}
	if loadToken != nil {
		opts.Token = loadToken()
	}
	// Only the GitLab path takes an instance URL. Passing one on the GitHub
	// path is what makes plumber choose the GitLab path — the flag is part of
	// how it decides — so it would send a GitHub context to a GitLab it has no
	// token for.
	if opts.Provider == providerGitLab {
		opts.GitLabURL = o.Forge.URL
	}
	return opts, true
}

// plumberProvider maps the configured forge onto --provider.
//
// Declared, never sniffed: the context says which forge it targets, so plumber
// is told rather than left to guess from the remote. An unrecognised type falls
// back to GitLab for applyDefaults' reason — it has already normalised the
// value, and the one backend that has always existed beats an error nothing can
// act on.
func plumberProvider(forgeType string) string {
	if forgeType == config.ForgeGitHub {
		return providerGitHub
	}
	return providerGitLab
}

// removing. The Title is not pre-truncated either — bubbles cuts every cell to
// its column width with the same ellipsis, and doing it by hand at width-3
// first only cost three characters of title.
func findingColumns() []datatable.Column[scan.Finding] {
	return []datatable.Column[scan.Finding]{
		{
			Title: "Severity", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell: func(f scan.Finding) string { return string(f.Severity) },
			// The same palette the selected row uses, so a severity reads the
			// same colour whether or not the cursor is on it.
			Style: func(f scan.Finding) lipgloss.Style { return theme.SeverityTextStyle(string(f.Severity)) },
			Less:  func(a, b scan.Finding) bool { return severityRank(a.Severity) < severityRank(b.Severity) },
		},
		{
			Title: "ID", Sizing: datatable.SizingContent, MinWidth: 18,
			Cell:   func(f scan.Finding) string { return f.ID },
			Less:   func(a, b scan.Finding) bool { return a.ID < b.ID },
			Search: func(f scan.Finding) string { return f.ID },
		},
		{
			Title: "Title", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1,
			Cell:   func(f scan.Finding) string { return f.Title },
			Less:   func(a, b scan.Finding) bool { return a.Title < b.Title },
			Search: func(f scan.Finding) string { return f.Title + " " + f.PkgName + " " + f.File },
		},
		{
			Title: "Source", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 14,
			Cell:   sourceDisplay,
			Less:   func(a, b scan.Finding) bool { return sourceDisplay(a) < sourceDisplay(b) },
			Search: sourceDisplay,
		},
	}
}

// severityRank orders the levels by how bad they are, which is the only order
// worth sorting this column by: alphabetically, CRITICAL lands between no two
// levels it belongs with — HIGH, LOW, MEDIUM — so a descending sort would put
// MEDIUM at the top and bury the finding the user opened the view for.
//
// Ascending is least-severe-first, so `.`'s second press (descending, Rule 111)
// is the one that answers "what is worst here".
//
// UNKNOWN ranks below LOW rather than above CRITICAL: it is what a scanner
// says when it has no score, not a claim that something is worse than critical.
// It has no token either, for the same reason — see severityToken.
func severityRank(s scan.SeverityLevel) int {
	switch s {
	case scan.SeverityCritical:
		return 4
	case scan.SeverityHigh:
		return 3
	case scan.SeverityMedium:
		return 2
	case scan.SeverityLow:
		return 1
	default:
		return 0
	}
}

// findingSelectedStyles colours the selected row by the severity under the
// cursor. It is what refreshSelectionStyle did, minus its own bounds check.
func findingSelectedStyles(f scan.Finding) table.Styles {
	return theme.TableStylesForSeverity(string(f.Severity))
}

// Tab constants for results view
const (
	TabCVE       = 0
	TabSecrets   = 1
	TabLicense   = 2
	TabMisconfig = 3
	TabCIScore   = 4
	// TabRemediation is not a category of finding: it has no entry in
	// tabCategory and its body is its own table (remediation.go).
	TabRemediation = 5
	tabCount       = 6
)

// updateFindingsTable populates the findings table based on active tab and filters.
//
// The tab is this view's own filter, not the component's: it selects which
// findings exist at all, where a FilterBar query narrows a list that is already
// settled. The severity went the other way — it is four cumulative tokens the
// table owns (Rule 136), which is what gave `.` back to the sort.
func (m *Model) updateFindingsTable() {
	if m.result == nil {
		return
	}

	m.findingsTable.SetItems(m.filterFindingsByTab())
	// A change of tab or severity is a change of scope, not a shorter list, so
	// the cursor goes back to the top and the columns are measured again.
	// SetItems deliberately does neither on its own.
	m.findingsTable.GotoTop()
	m.findingsTable.Remeasure()
}

// tabCategory maps a tab to the finding category it shows.
//
// The tabs and scan.Result's counters are now the same classification, applied
// once in scan.Categorize: they were two rules that disagreed on three inputs,
// each of which produced a finding counted in the header but present in no tab
// at all — visible nowhere, which is the worst way for a finding to be wrong.
var tabCategory = map[int]scan.Category{
	TabCVE:       scan.CategoryVulnerability,
	TabSecrets:   scan.CategorySecret,
	TabLicense:   scan.CategoryLicense,
	TabMisconfig: scan.CategoryMisconfiguration,
	TabCIScore:   scan.CategoryCIScore,
}

// filterFindingsByTab returns findings filtered by the active tab
func (m *Model) filterFindingsByTab() []scan.Finding {
	if m.result == nil {
		return nil
	}

	want, ok := tabCategory[m.activeTab]
	if !ok {
		return nil
	}
	var filtered []scan.Finding
	for _, f := range m.result.Findings {
		if scan.Categorize(f) == want {
			filtered = append(filtered, f)
		}
	}
	return filtered
}

// sourceDisplay returns a display string for the source column.
//
// Which tool found it, not which category it is — the tab already says the
// category, and telling gitleaks from trivy-secret in the Secrets tab is the
// point of showing both there.
func sourceDisplay(f scan.Finding) string {
	switch f.Source {
	case scan.SourceTrivyLicense:
		return "license"
	case scan.SourceTrivyMisconfig:
		return "misconfig"
	case scan.SourceGitleaks:
		return "gitleaks"
	case scan.SourceTrivySecret:
		return "trivy"
	case scan.SourceTrivy:
		return "vuln"
	default:
		return f.Source
	}
}

// countFindingsByTab returns the count of findings for each tab. These are the
// numbers on the tab labels, and scan.Result's counters are the same ones.
func (m *Model) countFindingsByTab() (cve, secrets, licenses, misconfigs, ci int) {
	if m.result == nil {
		return 0, 0, 0, 0, 0
	}

	for _, f := range m.result.Findings {
		switch scan.Categorize(f) {
		case scan.CategoryVulnerability:
			cve++
		case scan.CategorySecret:
			secrets++
		case scan.CategoryLicense:
			licenses++
		case scan.CategoryMisconfiguration:
			misconfigs++
		case scan.CategoryCIScore:
			ci++
		}
	}
	return cve, secrets, licenses, misconfigs, ci
}

// enterRemediationTab reads the Dockerfiles when the tab just switched to is the
// Remediation one, and does nothing on any other.
func (m *Model) enterRemediationTab() tea.Cmd {
	if m.activeTab != TabRemediation {
		return nil
	}
	return m.enterRemediation()
}

// switchTab switches to the given tab index and refreshes the table
func (m *Model) switchTab(tab int) {
	m.activeTab = tab
	// The CI tab carries a score line above the table, so the height changes
	// with the tab and not only with the window.
	m.resizeFindings()
	m.footer.Clear()
	m.updateFindingsTable()
}

// handleIgnoreSecret prompts confirmation to ignore a secret finding.
//
// Gitleaks findings only. .gitleaksignore is matched on a Gitleaks fingerprint,
// which a Trivy secret does not have — AddToGitleaksIgnore would fabricate one

		return "No results"
	}

	// A stage that failed is **not** rendered here. It goes to the log, and the
	// footer says to look there (Rule 128).
	//
	// It used to be a panel that replaced the whole table whenever
	// Result.Errors was non-empty, on the stated grounds that a failed scan has
	// no partial results to browse. That held while an error meant nothing had
	// run; it stopped holding the day a stage could fail beside three that
	// succeeded, and a plumber failure then took every CVE and every secret
	// down with it. Folding it to a banner above the table only moved the
	// problem — five tabs, permanently, for a message read once — and a tool's
	// stderr reformatted for a viewport is what a log is for.
	//
	// Nothing is lost by it: internal/scan logs every stage failure at the
	// point it records one, which it did not do before. The only copy of the
	// reason used to be on screen.
	//
	// The grade had a line of its own above the table on the CI tab, and it is
	// gone: it cost that tab two of its rows — the line and its blank — on
	// every open, to state a letter the inventory's own CI column carries per
	// target. A tab that shows fewer findings than its four neighbours, for a
	// value already on the previous screen, is not a trade worth making.
	if m.activeTab == TabRemediation {
		return m.remediation.table.View()
	}
	return m.findingsTable.View()
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	height := 2 // empty line + info line
	if m.showsResultTabs() {
		height = 3 // tab bar + empty line + info line
	}
	if bar := m.activeFilterBar(); bar != nil {
		height += bar.ExtraHeight() // Rule 136
	}
	return height
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
//
// The bar comes first whatever the state, because its top edge *is* the
// viewport's bottom border (Rule 136) — the same order oci_resources uses for
// the one bar it draws above a tab bar.
//
// It is resolved through activeFilterBar, like the height. The results branch
// drew no bar at all while GetFooterHeight counted one, so the router took two
// lines off the viewport and nothing filled them: the table's bottom border
// climbed the moment a severity token went on, and the tokens the user had just
// switched on were nowhere on screen.
func (m Model) RenderFooter(width int) string {
	var parts []string
	if bar := m.activeFilterBar(); bar != nil {
		parts = append(parts, bar.View())
	}
	if m.showsResultTabs() {
		parts = append(parts, theme.PadWithBg(theme.Bg(" ")+m.renderTabs(), width))
	}
	parts = append(parts, theme.EmptyLineBg(width), m.renderInfoLine(width))
	return strings.Join(parts, "\n")
}

// modalView renders whichever modal is open, or "" when none is.
func (m Model) modalView() string {
	switch {
	case m.confirmModal != nil:
		return m.confirmModal.View()
	case m.scanAllModal != nil:
		return m.scanAllModal.View()
	}
	return ""
}

// FilterBarVisible reports whether the filter bar is on screen, which is what
// closes the viewport's bottom border around it (implements app.FilterBarView,
// Rule 136). Both tables have one now: the findings table gained the four
// severity tokens that used to be a cycle on `.`.
func (m Model) FilterBarVisible() bool {
	return m.activeFilterBar() != nil
}

// activeFilterBar is the bar of whichever table is on screen, or nil when the
// state has no table. One resolution rather than three, so GetFooterHeight and
// RenderFooter cannot disagree about whether the bar is there — which is the
// one way to make Rule 124's arithmetic wrong by a line.
func (m Model) activeFilterBar() *sharedcomponents.FilterBar {
	var bar *sharedcomponents.FilterBar
	switch {
	case m.state == StateInventory:
		bar = m.inventory.FilterBar()
	case m.showsResultTabs() && m.activeTab != TabRemediation:
		// The Remediation tab has a table of its own and no filter: the bar
		// belongs to the findings table behind it.
		bar = m.findingsTable.FilterBar()
	}
	if bar == nil || !bar.IsVisible() {
		return nil
	}
	return bar
}

// showsResultTabs reports whether the findings tab bar is on screen.
//
// A failed stage no longer takes it away, because nothing replaces the table
// any more: the tabs are what the results state is browsed with, and an empty
// one is an honest answer — the footer says which stage failed and where to
// read why.
func (m Model) showsResultTabs() bool {
	return m.state == StateResults && m.result != nil
}

// renderInfoLine is the footer's message line, always rendered even when empty
// (Rule 124). The message expires on its own after three seconds (Rule 128).
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, m.status())
}

// status is what the footer says when no message is in flight.
//
// A stage that failed is a **state** of the result rather than an event: it is
// true for as long as the result is on screen, and a message would expire after
// three seconds — the distinction Rule 128 draws between the two. It carries
// the error level, because that is what happened, and it names the stages so
// the log can be searched for them.
func (m Model) status() sharedcomponents.Status {
	// A load in flight is a state too, and the only one the inventory has: the
	// table is on screen and empty, so without this line nothing distinguishes
	// "still reading the caches" from "nothing has ever been scanned".
	if m.state == StateInventory && m.inventoryLoading {
		return sharedcomponents.Status{Text: "Loading scan inventory...", Spinner: true}
	}
	// Ahead of the failed stages below: on this tab what is happening now is
	// what the footer is for, and a stage that failed still shows on the others.
	if status, ok := m.remediationStatus(); ok {
		return status
	}
	if m.state != StateResults || m.result == nil || len(m.result.Errors) == 0 {
		return sharedcomponents.Status{}
	}
	return sharedcomponents.Status{
		Text:  failedStages(m.result.Errors) + " — check logs",
		Level: sharedcomponents.LevelError,
	}
}

// failedStages names what failed, reading the "<stage>: <reason>" that
// scan.recordStageError writes. The reason stays in the log: a footer is one
// line, and a tool's stderr is not.
func failedStages(errs []string) string {
	stages := make([]string, 0, len(errs))
	for _, e := range errs {
		stage := e
		if idx := strings.Index(e, ": "); idx != -1 {
			stage = e[:idx]
		}
		stages = append(stages, stage)
	}
	return strings.Join(stages, ", ") + " failed"
}

// renderTabs renders the tab bar
func (m Model) renderTabs() string {
	cve, secrets, licenses, misconfigs, ci := m.countFindingsByTab()

	return theme.RenderTabs([]theme.TabItem{
		{Label: fmt.Sprintf("CVE (%d)", cve)},
		{Label: fmt.Sprintf("Secrets (%d)", secrets)},
		{Label: fmt.Sprintf("Licenses (%d)", licenses)},
		{Label: fmt.Sprintf("Misconfig (%d)", misconfigs)},
		// The count, like its four neighbours — not the letter. A letter in a
		// column of counts would break the only thing the tab bar keeps
		// aligned, and the grade already has a line of its own below.
		{Label: fmt.Sprintf("CI (%d)", ci)},
		{Label: m.remediationTabLabel()},
	}, m.activeTab)
}

	if m.findingsTable.InEditMode() {
		return shortcut.Shortcuts{{Key: "enter/esc", Description: "Confirm / Cancel search"}}
	}
	// X is greyed rather than dropped (Rule 130): a tab is not a different
	// screen, and the entry used to appear and disappear as the cursor crossed
	// a Trivy secret in a list holding both tools' findings.
	// The Remediation tab has a table of its own: what filters and sorts the
	// findings does not reach it, so those keys are greyed there and S — which
	// means nothing on the four tabs of findings — is the one that lights up.
	notFindings := m.activeTab == TabRemediation
	// Enter opens the selected finding, or on the Remediation tab the diff of the
	// chosen bases: one key, the same place in the column, a different verb.
	enter := shortcut.Shortcut{Key: "enter", Description: "Details", Disabled: !m.canOpenFinding().Enabled()}
	if notFindings {
		enter = shortcut.Shortcut{Key: "enter", Description: "Show diff", Disabled: !m.canPreviewRemediation().Enabled()}
	}
	// ctrl+o is one key with one verb — write the file — and the object it
	// writes is the tab's. The label changes with it so the column never
	// offers "Write Dockerfile" on a tab holding a Kubernetes manifest.
	writeShortcut := shortcut.Shortcut{Key: writeRemediationKey, Description: "Write Dockerfile", Disabled: !m.canWriteRemediation().Enabled()}
	if m.activeTab == TabMisconfig {
		writeShortcut = shortcut.Shortcut{Key: writeRemediationKey, Description: "Apply built-in fix", Disabled: !m.canFixMisconfig().Enabled()}
	}
	return []shortcut.Shortcut{
		{Key: "tab", Description: "Switch tab"},
		enter,
		{Key: "space", Description: "Choose candidate", Disabled: !m.canSelectCandidate().Enabled()},
		writeShortcut,
		{Key: keymap.Scan, Description: "Scan candidates", Disabled: !m.canScanCandidates().Enabled()},
		{Key: "c", Description: "Toggle CRITICAL", Disabled: notFindings},
		{Key: "h", Description: "Toggle HIGH", Disabled: notFindings},
		{Key: "m", Description: "Toggle MEDIUM", Disabled: notFindings},
		{Key: "l", Description: "Toggle LOW", Disabled: notFindings},
		{Key: "/", Description: "Search", Disabled: notFindings},
		{Key: ".", Description: "Sort", Disabled: notFindings},
		{Key: keymap.Exclude, Description: "Exclude", Disabled: !m.canExclude().Enabled()},
		{Key: openPipelineKey, Description: "Open resolved pipeline", Disabled: !m.canOpenPipeline().Enabled()},
		{Key: "ctrl+r", Description: "New scan"},
		{Key: "ctrl+p", Description: "Command"},
		{Key: "?", Description: "Help"},
	}
}

// inventoryShortcuts advertises only what the selected row can actually do
// (Rule 130). An empty inventory offers none of the per-row actions, and a row
// with no stored counts cannot be opened.
// inventoryShortcuts is the landing state's column.
//
// An empty inventory is the same screen as a full one — the table is there,
// with no rows — so the row actions are greyed rather than dropped (Rule 130).
// The first scan of a context used to make four entries appear at once.
func (m Model) inventoryShortcuts() shortcut.Shortcuts {
	_, hasRow := m.inventory.Selected()
	return []shortcut.Shortcut{
		{Key: "enter", Description: "Open findings", Disabled: !m.canOpenTarget().Enabled()},
		{Key: keymap.Scan, Description: "Rescan", Disabled: !m.canRescanSelected().Enabled()},
		{Key: keymap.ScanAll, Description: "Rescan all", Disabled: !m.canRescanAll().Enabled()},
		{Key: "/", Description: "Filter", Disabled: !hasRow},
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "ctrl+p", Description: "Command"},

