package mcp

import (
	"context"
	"fmt"
	"log"
	"sort"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/scan"
	sdk "github.com/modelcontextprotocol/go-sdk/mcp"
)

// The scan tools: what this context has already scanned, and what one scan
// found. They are most of why §3.38 is worth doing — an agent can run trivy
// itself, but it cannot know what has already been looked at.

// defaultFindingLimit and maxFindingLimit bound one page of findings. An image
// scan produces thousands, and a tool result is a message: returning all of them
// spends the agent's context on a list it was going to filter anyway.
const (
	defaultFindingLimit = 100
	maxFindingLimit     = 1000
)

// ── scan_inventory ──────────────────────────────────────────────────────────

type scanTarget struct {
	Kind       string    `json:"kind" jsonschema:"image or repository"`
	Name       string    `json:"name" jsonschema:"the reference of an image or the absolute path of a repository; this is what scan_result takes as its target"`
	Critical   int       `json:"critical"`
	High       int       `json:"high"`
	Medium     int       `json:"medium"`
	Low        int       `json:"low"`
	Sensitive  *bool     `json:"sensitive,omitempty" jsonschema:"whether a secret was found; absent means no stage looked which is not the same as none found"`
	ScannedAt  time.Time `json:"scanned_at"`
	AgeSeconds int64     `json:"age_seconds" jsonschema:"how long ago the scan ran so staleness can be judged without knowing the current time"`
}

type scanInventoryOut struct {
	Context string       `json:"context" jsonschema:"the context these targets belong to; repository entries are scoped to it while image entries are shared between contexts"`
	Targets []scanTarget `json:"targets"`
}

func registerScanInventory(s *sdk.Server, env *Env) {
	sdk.AddTool(s, &sdk.Tool{
		Name:        "scan_inventory",
		Description: toolDescription("scan_inventory"),
	}, func(_ context.Context, _ *sdk.CallToolRequest, _ any) (*sdk.CallToolResult, scanInventoryOut, error) {
		return nil, scanInventoryOut{Context: env.Context, Targets: inventory(env.Context)}, nil
	})
}

// inventory reads both scan caches and drops what no longer exists.
//
// The reconciliation is §3.37's, and both halves of its rule are kept: an image
// absent from the daemon's list is dropped, but an enumeration that *failed*
// keeps every image — "docker is not running" and "the image is gone" are the
// same silence from here, and reading the first as the second would empty the
// inventory the moment the daemon stops. A path is gone only on a definite
// absence.
//
// It hides, it never deletes. This server writes nothing at all.
func inventory(contextName string) []scanTarget {
	targets := make([]scanTarget, 0)
	now := time.Now()

	images, imagesKnown := docker.ImageNames()
	if entries, err := cache.ReadImageScanEntries(); err != nil {
		log.Printf("ERROR [mcp/scan] read image scan cache: %v", err)
	} else {
		for name, entry := range entries {
			if cache.ImageGone(name, images, imagesKnown) {
				continue
			}
			targets = append(targets, target(kindImage, name, entry.Critical, entry.High,
				entry.Medium, entry.Low, entry.Sensitive, entry.ScannedAt, now))
		}
	}

	if entries, err := cache.ReadWorkspaceScanEntries(contextName); err != nil {
		log.Printf("ERROR [mcp/scan] read workspace scan cache: %v", err)
	} else {
		for path, entry := range entries {
			if cache.RepositoryGone(path) {
				continue
			}
			targets = append(targets, target(kindRepository, path, entry.Critical, entry.High,
				entry.Medium, entry.Low, entry.Sensitive, entry.ScannedAt, now))
		}
	}

	// Both caches are maps, so their range order is deliberately random —
	// settling one here is what makes two successive calls comparable. CRITICAL
	// descending, for the reason the inventory view sorts that way: what the
	// list is consulted for goes on top.
	sort.Slice(targets, func(i, j int) bool {
		if targets[i].Critical != targets[j].Critical {
			return targets[i].Critical > targets[j].Critical
		}
		return strings.ToLower(targets[i].Name) < strings.ToLower(targets[j].Name)
	})
	return targets
}

func target(kind, name string, critical, high, medium, low int, sensitive *bool, scannedAt, now time.Time) scanTarget {
	t := scanTarget{
		Kind: kind, Name: name,
		Critical: critical, High: high, Medium: medium, Low: low,
		Sensitive: sensitive, ScannedAt: scannedAt,
	}
	if !scannedAt.IsZero() {
		t.AgeSeconds = int64(now.Sub(scannedAt).Seconds())
	}
	return t
}

// The seam and the two predicates are shared now — docker.ImageNames,
// cache.ImageGone, cache.RepositoryGone. This package held the second copy of
// each; the third reader had none, which is D69.

// ── scan_result ─────────────────────────────────────────────────────────────

// finding is what a scan finding looks like from outside DevDesk.
//
// It is a projection of scan.Finding and it has **no Match field**. That is the
// guarantee, not a filter applied on the way out: the string a secret scanner
// matched is the secret itself, so a field able to carry it is a field that gets
// filled in by accident one day. Rule, file, line and fingerprint identify the
// finding without reproducing it, which is where §3.10 already landed for
// Gitleaks triage.
type finding struct {
	ID          string   `json:"id"`
	Title       string   `json:"title"`
	Description string   `json:"description,omitempty"`
	Severity    string   `json:"severity"`
	Category    string   `json:"category" jsonschema:"vulnerability, secret, license or misconfiguration"`
	Source      string   `json:"source" jsonschema:"which scanner reported it"`
	File        string   `json:"file,omitempty"`
	Line        int      `json:"line,omitempty"`
	EndLine     int      `json:"end_line,omitempty" jsonschema:"last line of the faulty block, line being its first; absent means the span is unknown and must not be read as line zero"`
	Message     string   `json:"message,omitempty" jsonschema:"this instance's own wording, where description carries the rule's generic text"`
	Status      string   `json:"status,omitempty" jsonschema:"what the scanner concluded for this rule on this target"`
	Fingerprint string   `json:"fingerprint,omitempty" jsonschema:"identifies the finding for .gitleaksignore; it is not the matched string, which is never exposed"`
	PkgName     string   `json:"pkg_name,omitempty"`
	Version     string   `json:"version,omitempty"`
	FixedIn     string   `json:"fixed_in,omitempty"`
	Class       string   `json:"class,omitempty" jsonschema:"os-pkgs (fixed by the image's packages or a newer base image) or lang-pkgs (fixed only by bumping the dependency); empty on a result scanned before it was recorded"`
	Ecosystem   string   `json:"ecosystem,omitempty" jsonschema:"the package ecosystem, such as alpine, debian, gomod or npm"`
	Resolution  string   `json:"resolution,omitempty"`
	References  []string `json:"references,omitempty"`
}

type scanResultIn struct {
	Target   string   `json:"target" jsonschema:"an image reference or a repository path, exactly as scan_inventory reports it"`
	Severity []string `json:"severity,omitempty" jsonschema:"keep only these severities among CRITICAL HIGH MEDIUM LOW UNKNOWN; empty keeps every one"`
	Category []string `json:"category,omitempty" jsonschema:"keep only these categories among vulnerability secret license misconfiguration; empty keeps every one"`
	Offset   int      `json:"offset,omitempty" jsonschema:"how many findings to skip, for paging through a large scan"`
	Limit    int      `json:"limit,omitempty" jsonschema:"how many findings to return; defaults to 100 and is capped at 1000"`
}

type scanResultOut struct {
	Context   string    `json:"context" jsonschema:"the DevDesk context that served this answer"`
	Target    string    `json:"target"`
	ScannedAt time.Time `json:"scanned_at"`
	// TargetKind and Root say whether a finding's file can be opened at all
	// (§3.78). A misconfiguration found in an image points inside that image's
	// filesystem, which is not on disk and cannot be edited; the same rule in a
	// repository points at a file under Root. Without both, a caller acting on
	// a file path has no way to tell the two apart, and the first case reads
	// exactly like the second.
	TargetKind     string   `json:"target_kind" jsonschema:"image or repository; a finding's file is a path inside the image for an image target and cannot be opened on disk, while for a repository it is relative to root"`
	Root           string   `json:"root,omitempty" jsonschema:"absolute path a repository target's file paths are relative to; absent for an image target"`
	Critical       int      `json:"critical"`
	High           int      `json:"high"`
	Medium         int      `json:"medium"`
	Low            int      `json:"low"`
	Unknown        int      `json:"unknown"`
	SecretCount    int      `json:"secret_count"`
	SecretsScanned bool     `json:"secrets_scanned" jsonschema:"false means no secret stage ran, so secret_count says nothing about this target"`
	LicenseCount   int      `json:"license_count"`
	MisconfigCount int      `json:"misconfig_count"`
	Errors         []string `json:"errors,omitempty" jsonschema:"stages that failed; findings may be missing rather than absent"`

	Matched  int       `json:"matched" jsonschema:"how many findings the filters kept, before paging"`
	Total    int       `json:"total" jsonschema:"how many findings the scan holds in all"`
	Offset   int       `json:"offset"`
	Findings []finding `json:"findings"`
}

func registerScanResult(s *sdk.Server, env *Env) {
	sdk.AddTool(s, &sdk.Tool{
		Name:        "scan_result",
		Description: toolDescription("scan_result"),
	}, func(_ context.Context, _ *sdk.CallToolRequest, in scanResultIn) (*sdk.CallToolResult, scanResultOut, error) {
		name := strings.TrimSpace(in.Target)
		if name == "" {
			return nil, scanResultOut{}, fmt.Errorf("target is required — scan_inventory lists the names this context has results for")
		}

		result, kind, err := storedResult(name)
		if err != nil {
			return nil, scanResultOut{}, fmt.Errorf("no stored scan for %q in context %q — scan_inventory lists what there is, and a target it does not list has either never been scanned or no longer exists", name, env.Context)
		}

		return nil, project(env.Context, result, kind, in), nil
	})
}

// The two kinds of scan target, shared by the inventory and by scan_result so
// the two answers cannot drift on the wording.
const (
	kindImage      = "image"
	kindRepository = "repository"
)

// storedResult finds a target's stored findings without being told what kind of
// target it is, and says which kind answered.
//
// The caller has a name out of scan_inventory and nothing else, so asking it to
// carry the kind as well would be asking it to remember something it can look
// up. An image reference and an absolute path do not collide in practice.
//
// The kind comes from **which cache answered**, never from the shape of the
// name: a repository path that reads like an image reference exists, and
// deciding by inspection would send a caller writing into a path that is not
// there. The lookup already knows; it just used to discard the answer.
func storedResult(target string) (*scan.Result, string, error) {
	if result, err := cache.ReadImageScanResult(target); err == nil {
		return result, kindImage, nil
	}
	result, err := cache.ReadWorkspaceScanResult(target)
	if err != nil {
		return nil, "", err
	}
	return result, kindRepository, nil
}

// project turns a stored result into what leaves the process: the summary, the
// findings the filters kept, and one page of them.
func project(contextName string, result *scan.Result, kind string, in scanResultIn) scanResultOut {
	out := scanResultOut{
		Context:        contextName,
		Target:         result.Target,
		TargetKind:     kind,
		ScannedAt:      result.EndTime,
		Critical:       result.Counts.Critical,
		High:           result.Counts.High,
		Medium:         result.Counts.Medium,
		Low:            result.Counts.Low,
		Unknown:        result.Counts.Unknown,
		SecretCount:    result.SecretCount,
		SecretsScanned: result.SecretsScanned,
		LicenseCount:   result.LicenseCount,
		MisconfigCount: result.MisconfigCount,
		Errors:         result.Errors,
		Total:          len(result.Findings),
		Findings:       []finding{},
	}
	// Root is the repository itself: a workspace scan is run on that directory,
	// so a finding's file is relative to it. An image has no such anchor, which
	// is the whole point of the distinction.
	if kind == kindRepository {
		out.Root = result.Target
	}

	severities := normalisedSet(in.Severity, strings.ToUpper)
	categories := normalisedSet(in.Category, strings.ToLower)

	kept := make([]scan.Finding, 0, len(result.Findings))
	for _, f := range result.Findings {
		if len(severities) > 0 {
			if _, ok := severities[strings.ToUpper(string(f.Severity))]; !ok {
				continue
			}
		}
		if len(categories) > 0 {
			if _, ok := categories[categoryName(scan.Categorize(f))]; !ok {
				continue
			}
		}
		kept = append(kept, f)
	}
	out.Matched = len(kept)

	offset, limit := page(in.Offset, in.Limit)
	out.Offset = offset
	if offset >= len(kept) {
		return out
	}
	end := offset + limit
	if end > len(kept) {
		end = len(kept)
	}
	for _, f := range kept[offset:end] {
		out.Findings = append(out.Findings, expose(f))
	}
	return out
}

// page normalises what the caller asked for. A negative offset is a mistake, not
// a request to count from the end; an absent limit is the default and an
// oversized one is capped, because the cap protects the agent's own context and
// a caller cannot waive that on its behalf.
func page(offset, limit int) (int, int) {
	if offset < 0 {
		offset = 0
	}
	switch {
	case limit <= 0:
		limit = defaultFindingLimit
	case limit > maxFindingLimit:
		limit = maxFindingLimit
	}
	return offset, limit
}

// expose is the one place a scan.Finding becomes something that leaves the
// process. It names every field it copies, so a field added to scan.Finding
// arrives here as an omission rather than as an exposure — the same argument the
// allow-list of tools makes.
func expose(f scan.Finding) finding {
	return finding{
		ID:          f.ID,
		Title:       f.Title,
		Description: f.Description,
		Severity:    string(f.Severity),
		Category:    categoryName(scan.Categorize(f)),
		Source:      f.Source,
		File:        f.File,
		Line:        f.Line,
		EndLine:     f.EndLine,
		Message:     f.Message,
		Status:      f.Status,
		Fingerprint: f.Fingerprint,
		PkgName:     f.PkgName,
		Version:     f.Version,
		FixedIn:     f.FixedIn,
		Class:       f.Class,
		Ecosystem:   f.Ecosystem,
		Resolution:  f.Resolution,
		References:  f.References,
	}
}

// categoryName is scan.Category as a word. The type is an int with no String
// method, so a conversion would yield a rune rather than a name — and the four
// values are a vocabulary an agent filters on, which makes them part of the
// tool's contract rather than an internal enum.
//
// The default is "vulnerability" for the reason Categorize's is: a source this
// does not know stays visible in the family that is looked at first, rather than
// disappearing into a name nothing filters for.
func categoryName(c scan.Category) string {
	switch c {
	case scan.CategorySecret:
		return "secret"
	case scan.CategoryLicense:
		return "license"
	case scan.CategoryMisconfiguration:
		return "misconfiguration"
	default:
		return "vulnerability"
	}
}

func normalisedSet(values []string, normalise func(string) string) map[string]struct{} {
	out := make(map[string]struct{}, len(values))
	for _, v := range values {
		if v = normalise(strings.TrimSpace(v)); v != "" {
			out[v] = struct{}{}
		}
	}
	return out
}

package cache

import (
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/anthnel/devdesk/internal/scan"
)

// WorkspaceScanEntry holds cached CVE counts for a scanned workspace git repo
type WorkspaceScanEntry struct {
	RepoPath string `json:"repo_path"`
	Critical int    `json:"critical"`
	High     int    `json:"high"`
	Medium   int    `json:"medium"`
	Low      int    `json:"low"`
	// Sensitive is the secret verdict — same three values as on ImageScanEntry,
	// written by the same `scan.Result.SecretVerdict()`.
	//
	// The move from boolean to pointer loses nothing: the old field was
	// **always** written (`json:"sensitive"`, without omitempty), so a file
	// written by a previous version decodes to a non-nil pointer, verdict
	// included. What the pointer adds is the case that was missing: a
	// secrets stage cut off by the option or by a missing tool used to
	// render `false`, i.e. "clean", for a scan that had not looked.
	Sensitive *bool `json:"sensitive,omitempty"`
	// CIScore is the pipeline grade, written by scan.Result.CIVerdict(), and it
	// is a pointer for exactly Sensitive's reason: nil means nobody graded this
	// repository — the option is off, plumber is absent, the repository is not
	// this context's forge, or the run was withheld. A letter is a claim, and
	// an empty string in its place would be a fifth state nothing means.
	//
	// The field has never been written, so an existing cache file decodes to
	// nil, which is the truth about it. ImageScanEntry gains nothing: an image
	// has no pipeline.
	CIScore   *string   `json:"ci_score,omitempty"`
	ScannedAt time.Time `json:"scanned_at"`
}

// WorkspaceScanCache manages workspace scan results cache.
//
// Bound to one configuration context, like ImageScanCache: workspaces_dir is
// per context, so two contexts legitimately hold different roots.
type WorkspaceScanCache struct {
	mu       sync.RWMutex
	path     string
	context  string
	contexts map[string]map[string]WorkspaceScanEntry // context → repo path → entry
}

// NewWorkspaceScanCache creates or loads the cache from
// ~/.devdesk/cache/workspace-scans.json, scoped to a configuration context.
func NewWorkspaceScanCache(context string) (*WorkspaceScanCache, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return nil, err
	}

	cacheDir := filepath.Join(homeDir, ".devdesk", "cache")
	if err := os.MkdirAll(cacheDir, 0755); err != nil {
		return nil, err
	}

	return newWorkspaceScanCacheAt(filepath.Join(cacheDir, "workspace-scans.json"), context)
}

// newWorkspaceScanCacheAt is NewWorkspaceScanCache without the home-directory
// lookup, so tests can point at a temp file.
func newWorkspaceScanCacheAt(path, context string) (*WorkspaceScanCache, error) {
	c := &WorkspaceScanCache{
		path:     path,
		context:  context,
		contexts: make(map[string]map[string]WorkspaceScanEntry),
	}
	c.load()
	return c, nil
}

// load reads the cache file from disk
func (c *WorkspaceScanCache) load() {
	contexts, err := readScanCacheFile[WorkspaceScanEntry](c.path, c.context)
	if err != nil {
		log.Printf("ERROR [cache/workspace_scan] read cache file %s: %v", c.path, err)
		return
	}
	c.contexts = contexts
}

// entries returns this context's map, creating it on first write.
// Must be called with the lock held.
func (c *WorkspaceScanCache) entries() map[string]WorkspaceScanEntry {
	return entriesFor(c.contexts, c.context)
}

// save writes the cache to disk (must be called with lock held)
func (c *WorkspaceScanCache) save() error {
	return writeScanCacheFile(c.path, c.contexts)
}

// Get returns the cached scan entry for a repo path, or nil if not found
func (c *WorkspaceScanCache) Get(repoPath string) *WorkspaceScanEntry {
	c.mu.RLock()
	defer c.mu.RUnlock()
	if entry, ok := c.contexts[c.context][repoPath]; ok {
		return &entry
	}
	return nil
}

// Set stores a scan entry and persists to disk
func (c *WorkspaceScanCache) Set(repoPath string, entry WorkspaceScanEntry) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.entries()[repoPath] = entry
	return c.save()
}

// GetAll returns all cached entries for this context
func (c *WorkspaceScanCache) GetAll() map[string]WorkspaceScanEntry {
	c.mu.RLock()
	defer c.mu.RUnlock()
	own := c.contexts[c.context]
	result := make(map[string]WorkspaceScanEntry, len(own))
	for k, v := range own {
		result[k] = v
	}
	return result
}

// Delete removes one entry from this context and persists to disk
func (c *WorkspaceScanCache) Delete(repoPath string) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	delete(c.contexts[c.context], repoPath)
	return c.save()
}

// Reload re-reads the cache from disk
func (c *WorkspaceScanCache) Reload() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.load()
}

// workspaceScanResultDir returns the directory for full scan results, creating it if needed
func workspaceScanResultDir() (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	dir := filepath.Join(homeDir, ".devdesk", "cache", "workspace-results")
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", err
	}
	return dir, nil
}

// resultFilePath returns the JSON file path for the full scan result of a repo path.
// Uses SHA256 of the path to avoid invalid filename characters.
func resultFilePath(repoPath string) (string, error) {
	dir, err := workspaceScanResultDir()
	if err != nil {
		return "", err
	}
	hash := sha256.Sum256([]byte(repoPath))
	filename := fmt.Sprintf("%x.json", hash)
	return filepath.Join(dir, filename), nil
}

// SaveWorkspaceScanResult persists a full scan result to disk.
// Designed to be called in a goroutine: go SaveWorkspaceScanResult(path, result)
func SaveWorkspaceScanResult(repoPath string, result *scan.Result) error {
	filePath, err := resultFilePath(repoPath)
	if err != nil {
		return err
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(filePath, data, 0600)
}

// StoreWorkspaceScan records one finished scan of a directory: the counts in the
// cache of the context the scan was launched in, and the full result beside it.
//
// The counts are scoped by context and the result is not — it is addressed by
// path, and a scan of /repos/devdesk is the same scan whichever context asked
// (see internal/cache/scan_context_test.go). Two callers write exactly this: the
// workspaces view for a repository, and the templates view for a template's
// materialized copy.
//
// A failure to save either half is logged and returned, but the entry is
// returned regardless: the scan happened, and its counts are what the caller
// reports.
func StoreWorkspaceScan(contextName, repoPath string, result *scan.Result) (WorkspaceScanEntry, error) {
	entry := WorkspaceScanEntry{
		RepoPath: repoPath,
		Critical: result.Counts.Critical,
		High:     result.Counts.High,
		Medium:   result.Counts.Medium,
		Low:      result.Counts.Low,
		// The verdict comes from the scan and from nowhere else: a loop looking
		// for "a finding whose Source is gitleaks" missed the secrets Trivy
		// found, and could not tell that no stage had looked at all.
		Sensitive: result.SecretVerdict(),
		CIScore:   result.CIVerdict(),
		ScannedAt: result.EndTime,
	}

	var errs []error
	if wc, err := NewWorkspaceScanCache(contextName); err != nil {
		errs = append(errs, fmt.Errorf("open cache: %w", err))
	} else if err := wc.Set(repoPath, entry); err != nil {
		errs = append(errs, fmt.Errorf("cache set: %w", err))
	}
	if err := SaveWorkspaceScanResult(repoPath, result); err != nil {
		errs = append(errs, fmt.Errorf("save full result: %w", err))
	}
	return entry, errors.Join(errs...)
}

// DeleteWorkspaceScanResult removes the full scan result file from disk.
// Used by purgeScanCacheCmd before re-scanning to avoid stale results.
func DeleteWorkspaceScanResult(repoPath string) error {
	filePath, err := resultFilePath(repoPath)
	if err != nil {
		return err
	}
	err = os.Remove(filePath)
	if errors.Is(err, fs.ErrNotExist) {
		return nil // already gone, not an error
	}
	return err
}

// LoadWorkspaceScanResult loads a full scan result from disk
func LoadWorkspaceScanResult(repoPath string) (*scan.Result, error) {
	filePath, err := resultFilePath(repoPath)
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(filePath)
	if err != nil {
		return nil, err
	}
	var result scan.Result
	if err := json.Unmarshal(data, &result); err != nil {
		return nil, err
	}
	return &result, nil
}

